// Recipe book contract types. The structural shapes come from the generated
// mirror (app/generated/recipeBookContract.ts — source of truth:
// shopman/backstage/projections/recipe_book.py, regenerated by
// `python manage.py export_recipe_book_schema`). This module only narrows the
// fields the backend types as plain `str`, declares the API envelopes
// (RECIPE-INVENTORY-PLAN §8) and the WRITE payload of a formula (§3) — the one
// shape the surface authors, everything else arrives screen-ready (ADR-014).

import type {
  FormulaLensProjection,
  IngredientOptionProjection,
  RecipeBookAccessProjection,
  RecipeBookListProjection,
  RecipeCaptureDraftProjection,
  RecipeCompareProjection,
  RecipeEntryDetailProjection,
  RecipeReferenceProjection,
  RecipeReviewQueueProjection,
  RecipeSheetDetailProjection,
  RecipeSheetListProjection,
  RecipeVersionProjection,
} from "~/generated/recipeBookContract";

export type {
  CaptureItemProjection,
  CriterionAverageProjection,
  ExternalReferenceProjection,
  FormulaItemProjection,
  FormulaLensProjection,
  FormulaMetricProjection,
  FormulaPrepProjection,
  FormulaWarningProjection,
  ExecutionSheetProjection,
  IngredientOptionProjection,
  KindOptionProjection,
  LifecycleOptionProjection,
  QualityShareProjection,
  RatingCriterionProjection,
  RecipeBookAccessProjection,
  RecipeBookListProjection,
  RecipeCaptureDraftProjection,
  RecipeCompareMetricProjection,
  RecipeCompareProjection,
  RecipeCompareRowProjection,
  RecipeEntryCardProjection,
  RecipeEntryDetailProjection,
  RecipeReferenceProjection,
  RecipeReviewItemProjection,
  RecipeReviewQueueProjection,
  RecipeSheetCardProjection,
  RecipeSheetDetailProjection,
  RecipeSheetItemProjection,
  RecipeSheetListProjection,
  RecipeSheetMassBalanceProjection,
  RecipeStepProjection,
  RecipeUsageProjection,
  RecipeVersionProjection,
  ReferenceRangeProjection,
  UsageCaveatProjection,
  VersionRatingProjection,
  VersionUsageProjection,
} from "~/generated/recipeBookContract";

// ── Vocabulário estreitado (o backend manda `str`) ──────────────────────────

/** Tom funcional das métricas, avisos e deltas: calmo por padrão. */
export type LensTone = "ok" | "warning" | "muted";

export type RecipeKind =
  | "bread"
  | "viennoiserie"
  | "sweet_dough"
  | "cookie"
  | "filling"
  | "cream"
  | "sauce"
  | "beverage"
  | "other";

export type VersionStatus = "draft" | "published" | "superseded";

export type AnchorKind = "flour" | "total" | "ingredient";

export type IngredientRole =
  | "flour"
  | "liquid"
  | "salt"
  | "yeast"
  | "fat"
  | "sugar"
  | "egg"
  | "dairy"
  | "inclusion"
  | "other";

export type FormulaUnit = "g" | "kg" | "ml" | "L" | "un";

export type PrepKind = "preferment" | "autolyse" | "soaker" | "old_dough";

export type YieldUnit = "kg" | "g" | "un" | "L" | "ml";

/** `RecipeUsageProjection.bake_loss_basis`: "" = receita sem ficha ativa. */
export type BakeLossBasis = "" | "house_default" | "estimated" | "weighed";

/** Avisos que viajam com o uso por versão: o que os números NÃO medem. */
export type UsageCaveatCode =
  | "loss_is_residual"
  | "unversioned_not_attributed"
  | "bake_loss_house_default"
  | "bake_loss_estimated";

// ── Payload de escrita: `RecipeVersion.formula` (§3) ────────────────────────

export interface FormulaAnchor {
  kind: AnchorKind;
  /** Só com `kind: "ingredient"`: o SKU-âncora (o leite de um creme). */
  sku?: string;
}

export interface FormulaItem {
  /** "" = ingrediente ainda não casado com insumo (permitido em rascunho). */
  sku: string;
  name: string;
  role: IngredientRole;
  quantity: number;
  unit: FormulaUnit;
  note?: string;
  /** Contagem (`un`) só entra na conta com gramas por unidade. */
  grams_per_unit?: number | null;
  /** Volume vira grama pela densidade; sem ela, 1,0 para líquido (com aviso). */
  density_g_per_ml?: number | null;
}

export interface FormulaPrep {
  sku?: string;
  entry_ref?: string;
  kind: PrepKind;
  /** Percentual da base de farinha que passa pela prep. */
  flour_pct?: number | null;
  /** Prep sem base de farinha: quantidade declarada. */
  quantity?: number | null;
  unit?: FormulaUnit;
  /** Só `old_dough`: teto da fórmula inteira. */
  cap_pct?: number | null;
}

export interface Formula {
  anchor: FormulaAnchor;
  basis_g: number | null;
  standardized: boolean;
  items: FormulaItem[];
  preps: FormulaPrep[];
}

/**
 * Uma etapa como a API a recebe (`shopman/craftsman/recipe_steps.py`). Vazio
 * e `null` saem no servidor; só `name` é obrigatório.
 */
export interface RecipeStepInput {
  name: string;
  instructions?: string;
  target_seconds?: number | null;
  temperature_celsius?: number | null;
  note?: string;
}

/** Corpo de `POST recipes/<ref>/versions/` e do `version` de `POST recipes/`. */
export interface VersionPayload {
  expectedRevision?: string;
  from_version?: number;
  formula: Formula;
  yield_quantity: string;
  yield_unit: string;
  steps?: RecipeStepInput[];
  notes?: string;
  label?: string;
  origin?: Record<string, unknown>;
  source?: Record<string, unknown>;
}

/** Campos do rascunho aceitos por `PATCH recipes/<ref>/versions/<n>/`. */
export interface DraftPatch {
  expectedRevision?: string;
  formula?: Formula;
  yield_quantity?: string;
  yield_unit?: string;
  steps?: RecipeStepInput[];
  notes?: string;
  label?: string;
}

/** Corpo de `POST recipes/`. */
export interface EntryCreatePayload {
  ref?: string;
  name: string;
  kind: string;
  output_sku: string;
  notes: string;
  version?: VersionPayload;
}

/**
 * Uma referência externa como a API a recebe (`RecipeEntry.meta["external_references"]`):
 * livro, vídeo ou artigo. Só `title` é obrigatório; `url` só http/https.
 */
export interface ExternalReferenceInput {
  title: string;
  url?: string;
  note?: string;
}

/** Corpo de `PATCH recipes/<ref>/`. `external_references` substitui a lista inteira. */
export interface EntryPatch {
  name?: string;
  kind?: string;
  output_sku?: string;
  notes?: string;
  is_active?: boolean;
  external_references?: ExternalReferenceInput[];
  expectedRevision?: string;
}

export interface RecipeDuplicatePayload {
  name: string;
  ref?: string;
  outputSku?: string;
  fromVersion?: number;
  expectedRevision: string;
}

export interface ExecutionPatch {
  expectedRevision: string;
  maxStartedMinutes?: number | null;
  capacityPerDay?: string | null;
  requiresBatchTracking?: boolean;
  shelfLifeDays?: number | null;
  shelfLifeReviewed?: boolean;
  productionLifecycle?: string;
  /** `Recipe.production_mode`: "batch" (Em lote) ou "made_to_order" (Na hora). */
  productionMode?: string;
}

/** Corpo de `PUT recipes/<ref>/versions/<n>/rating/`: id do critério → nota inteira de 0 a 5. */
export interface RatingPayload {
  scores: Record<string, number>;
}

/** Corpo de `POST recipes/capture/`. */
export interface CaptureImagePayload {
  data_base64: string;
  media_type: string;
}

// ── Envelopes da API (§8) ───────────────────────────────────────────────────

export interface RecipeBookListResponse {
  book: RecipeBookListProjection;
  access: RecipeBookAccessProjection;
}

export interface RecipeReviewQueueResponse {
  queue: RecipeReviewQueueProjection;
  access: RecipeBookAccessProjection;
}

export interface RecipeEntryResponse {
  entry: RecipeEntryDetailProjection;
  access?: RecipeBookAccessProjection;
}

export interface RecipeDuplicateResponse extends RecipeEntryResponse {
  ok: boolean;
  outcome: "applied" | "not_applied" | "unknown";
  resource: { kind: "recipe"; ref: string };
}

export type RecipeCreateResponse = RecipeDuplicateResponse;
export interface RecipeVersionMutationResponse extends RecipeEntryResponse {
  version?: RecipeVersionProjection;
  ok: boolean;
  outcome: "applied" | "not_applied" | "unknown";
  resource: { kind: "recipe-version"; ref: string };
}

/** POST/DELETE recipes/<ref>/favorite/ — a estrela do operador, idempotente. */
export interface RecipeFavoriteResponse {
  ref: string;
  is_favorite: boolean;
}

export interface RecipeVersionResponse {
  entry: RecipeEntryDetailProjection;
  version: RecipeVersionProjection;
}

export interface LensResponse {
  lens: FormulaLensProjection;
}

export interface StandardizeResponse {
  formula: Formula;
  lens: FormulaLensProjection;
}

export interface CompareResponse {
  compare: RecipeCompareProjection;
}

export interface ReferenceResponse {
  reference: RecipeReferenceProjection;
}

export interface IngredientsResponse {
  options: IngredientOptionProjection[];
}

export interface CaptureResponse {
  draft: RecipeCaptureDraftProjection;
}

export interface AccessResponse {
  access: RecipeBookAccessProjection;
}

// ── Ficha de execução (cadastro direto de craftsman.Recipe + RecipeItem) ────

/** Uma linha da ficha como o formulário a edita (valores crus, sem projeção). */
export interface RecipeSheetItemDraft {
  inputSku: string;
  quantity: string;
  unit: string;
  usableFactor: string;
  isOptional: boolean;
  note: string;
}

/** Uma linha da ficha como a API a recebe. */
export interface RecipeSheetItemPayload {
  input_sku: string;
  quantity: string;
  unit: string;
  usable_factor: string;
  sort_order?: number;
  is_optional: boolean;
  note: string;
}

/**
 * Corpo de `POST sheets/` e de `PATCH sheets/<ref>/`. A identidade e o BOM
 * falam snake_case (o dialeto das entry de receita); a operação fala o mesmo
 * camelCase do `/execution/`, porque é o MESMO serviço que a aplica.
 */
export interface RecipeSheetPayload {
  name: string;
  ref?: string;
  output_sku: string;
  batch_size: string;
  is_active?: boolean;
  steps?: RecipeStepInput[];
  items: RecipeSheetItemPayload[];
  expectedRevision?: string;
  maxStartedMinutes?: number | null;
  capacityPerDay?: string | null;
  requiresBatchTracking?: boolean;
  shelfLifeDays?: number | null;
  shelfLifeReviewed?: boolean;
  productionLifecycle?: string;
  productionMode?: string;
}

/** Corpo de `POST sheets/<ref>/duplicate/`: a cópia nasce inativa. */
export interface RecipeSheetDuplicatePayload {
  name: string;
  ref?: string;
  output_sku?: string;
  expectedRevision: string;
}

export interface RecipeSheetListResponse {
  sheets: RecipeSheetListProjection;
  access: RecipeBookAccessProjection;
}

export interface RecipeSheetResponse {
  sheet: RecipeSheetDetailProjection;
  access?: RecipeBookAccessProjection;
}

export interface RecipeSheetMutationResponse extends RecipeSheetResponse {
  ok: boolean;
  outcome: "applied" | "not_applied" | "unknown";
  resource: { kind: "recipe-sheet"; ref: string };
}

